{
  "items": [
    {
      "name": "Finset.apply_union_le_sum",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_2} {β : Type u_3} [inst : AddCommMonoid β] [inst_1 : PartialOrder β] [AddLeftMono β]\n  {f : Set α → β},\n  f ∅ = 0 →\n    (∀ {s t : Set α}, f (s ∪ t) ≤ f s + f t) → ∀ {s : ι → Set α} (t : Finset ι), f (⋃ i ∈ t, s i) ≤ ∑ i ∈ t, f (s i)"
    },
    {
      "name": "Finsupp.sum_le_sum",
      "module_name": "Mathlib.Data.Finsupp.Order",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {α : Type u_3} {β : Type u_4} [inst : Zero α] [inst_1 : AddCommMonoid β] [inst_2 : PartialOrder β]\n  [IsOrderedAddMonoid β] {f : ι →₀ α} {h₁ h₂ : ι → α → β},\n  (∀ i ∈ f.support, h₁ i (f i) ≤ h₂ i (f i)) → f.sum h₁ ≤ f.sum h₂"
    },
    {
      "name": "Finset.le_sum_of_subadditive_on_pred",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} {N : Type u_5} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N]\n  [inst_2 : PartialOrder N] [IsOrderedAddMonoid N] (f : M → N) (p : M → Prop),\n  f 0 ≤ 0 →\n    (∀ (x y : M), p x → p y → f (x + y) ≤ f x + f y) →\n      (∀ (x y : M), p x → p y → p (x + y)) →\n        ∀ (g : ι → M) {s : Finset ι}, (∀ i ∈ s, p (g i)) → f (∑ i ∈ s, g i) ≤ ∑ i ∈ s, f (g i)"
    },
    {
      "name": "ENNReal.tsum_union_le",
      "module_name": "Mathlib.Topology.Algebra.InfiniteSum.ENNReal",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (f : α → ENNReal) (s t : Set α), ∑' (x : ↑(s ∪ t)), f ↑x ≤ ∑' (x : ↑s), f ↑x + ∑' (x : ↑t), f ↑x"
    },
    {
      "name": "Finset.le_sum_of_subadditive",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} {N : Type u_5} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N]\n  [inst_2 : PartialOrder N] [IsOrderedAddMonoid N] (f : M → N),\n  f 0 ≤ 0 → (∀ (x y : M), f (x + y) ≤ f x + f y) → ∀ (s : Finset ι) (g : ι → M), f (∑ i ∈ s, g i) ≤ ∑ i ∈ s, f (g i)"
    },
    {
      "name": "Finset.le_sum_nonempty_of_subadditive_on_pred",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {M : Type u_4} {N : Type u_5} [inst : AddCommMonoid M] [inst_1 : AddCommMonoid N]\n  [inst_2 : PartialOrder N] [IsOrderedAddMonoid N] (f : M → N) (p : M → Prop),\n  (∀ (x y : M), p x → p y → f (x + y) ≤ f x + f y) →\n    (∀ (x y : M), p x → p y → p (x + y)) →\n      ∀ (g : ι → M) (s : Finset ι), s.Nonempty → (∀ i ∈ s, p (g i)) → f (∑ i ∈ s, g i) ≤ ∑ i ∈ s, f (g i)"
    }
  ]
}

