      "module_name": "Mathlib.Algebra.Order.AbsoluteValue.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u_5} {S : Type u_6} [inst : Semiring R] [inst_1 : Semiring S] [inst_2 : PartialOrder S]\n  (abv : AbsoluteValue R S) [AddLeftMono S] (l : List R), abv l.sum ≤ (List.map (⇑abv) l).sum"
    },
    {
      "name": "Finset.abs_sum_le_sum_abs",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {G : Type u_9} [inst : AddCommGroup G] [inst_1 : LinearOrder G] [IsOrderedAddMonoid G] (f : ι → G)\n  (s : Finset ι), |∑ i ∈ s, f i| ≤ ∑ i ∈ s, |f i|"
    },
    {
      "name": "IsAbsoluteValue.abv_add",
      "module_name": "Mathlib.Algebra.Order.AbsoluteValue.Basic",
      "kind": "theorem",
      "type": "∀ {S : Type u_5} [inst : Semiring S] [inst_1 : PartialOrder S] {R : Type u_6} [inst_2 : Semiring R] (abv : R → S)\n  [IsAbsoluteValue abv] (x y : R), abv (x + y) ≤ abv x + abv y"
    },
    {
      "name": "Multiset.abs_sum_le_sum_abs",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Group.Multiset",
      "kind": "theorem",
      "type": "∀ {α : Type u_2} [inst : AddCommGroup α] [inst_1 : LinearOrder α] [IsOrderedAddMonoid α] {s : Multiset α},\n  |s.sum| ≤ (Multiset.map abs s).sum"
    },
    {
      "name": "nnnorm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) (f : ι → E),\n  ‖∑ a ∈ s, f a‖₊ ≤ ∑ a ∈ s, ‖f a‖₊"
    },
    {
      "name": "IsAbsoluteValue.abv_sum",
      "module_name": "Mathlib.Algebra.Order.BigOperators.Ring.Finset",
      "kind": "theorem",
      "type": "∀ {ι : Type u_1} {R : Type u_2} {S : Type u_3} [inst : Semiring R] [inst_1 : Semiring S] [inst_2 : PartialOrder S]\n  [IsOrderedRing S] (abv : R → S) [IsAbsoluteValue abv] (f : ι → R) (s : Finset ι),\n  abv (∑ i ∈ s, f i) ≤ ∑ i ∈ s, abv (f i)"
    }
  ]
}

{
  "items": [
    {
      "name": "norm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_9} [inst : SeminormedAddCommGroup E] (s : Finset ι) (f : ι → E),\n  ‖∑ i ∈ s, f i‖ ≤ ∑ i ∈ s, ‖f i‖"
    },
    {
      "name": "MeasureTheory.eLpNorm_sum_le",
      "module_name": "Mathlib.MeasureTheory.Function.LpSeminorm.TriangleInequality",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ε' : Type u_4} {m : MeasurableSpace α} [inst : TopologicalSpace ε']\n  [inst_1 : ESeminormedAddCommMonoid ε'] {p : ENNReal} {μ : MeasureTheory.Measure α} [ContinuousAdd ε'] {ι : Type u_5}\n  {f : ι → α → ε'} {s : Finset ι},\n  (∀ i ∈ s, MeasureTheory.AEStronglyMeasurable (f i) μ) →\n    1 ≤ p → MeasureTheory.eLpNorm (∑ i ∈ s, f i) p μ ≤ ∑ i ∈ s, MeasureTheory.eLpNorm (f i) p μ"
    },
    {
      "name": "Real.Lp_add_le",
      "module_name": "Mathlib.Analysis.MeanInequalities",
      "kind": "theorem",
      "type": "∀ {ι : Type u} (s : Finset ι) (f g : ι → ℝ) {p : ℝ},\n  1 ≤ p → (∑ i ∈ s, |f i + g i| ^ p) ^ (1 / p) ≤ (∑ i ∈ s, |f i| ^ p) ^ (1 / p) + (∑ i ∈ s, |g i| ^ p) ^ (1 / p)"
    },
    {
      "name": "nnnorm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) (f : ι → E),\n  ‖∑ a ∈ s, f a‖₊ ≤ ∑ a ∈ s, ‖f a‖₊"
    },
    {
      "name": "nnnorm_sum_le_of_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {E : Type u_5} [inst : SeminormedAddCommGroup E] (s : Finset ι) {f : ι → E} {n : ι → NNReal},\n  (∀ b ∈ s, ‖f b‖₊ ≤ n b) → ‖∑ b ∈ s, f b‖₊ ≤ ∑ b ∈ s, n b"
    },
    {
      "name": "enorm_sum_le",
      "module_name": "Mathlib.Analysis.Normed.Group.Basic",
      "kind": "theorem",
      "type": "∀ {ι : Type u_3} {ε : Type u_9} [inst : TopologicalSpace ε] [inst_1 : ESeminormedAddCommMonoid ε] (s : Finset ι)\n  (f : ι → ε), ‖∑ i ∈ s, f i‖ₑ ≤ ∑ i ∈ s, ‖f i‖ₑ"
    }
  ]
}

