      "name": "MvPolynomial.coeff_monomial_mul'",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (m s : σ →₀ ℕ) (r : R) (p : MvPolynomial σ R) : ((MvPolynomial.monomial s) r * p).coeff m = if s ≤ m then r * p.coeff (m - s) else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeff_mul_monomial'",
      "type": " {R : Type u} {σ : Type u_1} [CommSemiring R] (m s : σ →₀ ℕ) (r : R) (p : MvPolynomial σ R) : (p * (MvPolynomial.monomial s) r).coeff m = if s ≤ m then p.coeff (m - s) * r else 0",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeffsIn_le",
      "type": " {R : Type u_2} {S : Type u_3} {σ : Type u_4} [CommSemiring R] [CommSemiring S] [Module R S] {M : Submodule R S} {N : Submodule R (MvPolynomial σ S)} : MvPolynomial.coeffsIn σ M ≤ N ↔ ∀ m ∈ M, ∀ (i : σ →₀ ℕ), (MvPolynomial.monomial i) m ∈ N",
      "module": "Mathlib.Algebra.MvPolynomial.Basic"
    },
    {
      "name": "MvPolynomial.coeffs_map",
      "type": " {R : Type u} {S₁ : Type v} {σ : Type u_1} [CommSemiring R] [CommSemiring S₁] (f : R →+* S₁) (p : MvPolynomial σ R) [DecidableEq S₁] : ((MvPolynomial.map f) p).coeffs ⊆ Finset.image (⇑f) p.coeffs",
      "module": "Mathlib.Algebra.MvPolynomial.Eval"
    },
    {
      "name": "MvPolynomial.coeff_modMonomial_of_le",
      "type": " {σ : Type u_1} {R : Type u_2} [CommSemiring R] {s' s : σ →₀ ℕ} (x : MvPolynomial σ R) (h : s ≤ s') : (x.modMonomial s).coeff s' = 0",
      "module": "Mathlib.Algebra.MvPolynomial.Division"
    },
    {
      "name": "MvPolynomial.coeff_modMonomial_of_not_le",
      "type": " {σ : Type u_1} {R : Type u_2} [CommSemiring R] {s' s : σ →₀ ℕ} (x : MvPolynomial σ R) (h : ¬s ≤ s') : (x.modMonomial s).coeff s' = x.coeff s'",
      "module": "Mathlib.Algebra.MvPolynomial.Division"
    }
